// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract MessageQueueConsumer is ReentrancyGuard, Ownable {
    enum QueueState { ACTIVE, DRAINING, SHUTDOWN }

    struct Message {
        address sender;
        bytes payload;
        uint256 timestamp;
        uint256 nonce;
        bool processed;
    }

    struct ConsumerState {
        uint256 headIndex;
        uint256 tailIndex;
        uint256 processedCount;
        uint256 lastProcessedTimestamp;
        QueueState state;
    }

    mapping(uint256 => Message) public messageQueue;
    ConsumerState public consumerState;
    mapping(address => uint256) public pendingWithdrawals;
    mapping(address => uint256) public processorRewards;

    uint256 public constant DRAIN_TIMEOUT = 30;
    uint256 public constant REWARD_PER_MESSAGE = 0.001 ether;
    uint256 public drainInitiatedAt;

    event MessageEnqueued(uint256 indexed index, address sender);
    event MessageProcessed(uint256 indexed index, address processor);
    event ShutdownInitiated(uint256 timestamp);
    event GracefulShutdownComplete(uint256 finalProcessedCount);

    modifier whenActive() {
        require(consumerState.state == QueueState.ACTIVE, "Queue not active");
        _;
    }

    modifier whenNotShutdown() {
        require(consumerState.state != QueueState.SHUTDOWN, "Queue shutdown");
        _;
    }

    constructor() {
        consumerState.state = QueueState.ACTIVE;
    }

    function enqueueMessage(bytes calldata payload) external payable whenActive {
        require(msg.value >= 0.01 ether, "Insufficient fee");

        uint256 index = consumerState.tailIndex;
        messageQueue[index] = Message({
            sender: msg.sender,
            payload: payload,
            timestamp: block.timestamp,
            nonce: index,
            processed: false
        });
        consumerState.tailIndex = index + 1;

        emit MessageEnqueued(index, msg.sender);
    }

    function processNextMessage() external nonReentrant whenNotShutdown returns (bool) {
        uint256 head = consumerState.headIndex;
        uint256 tail = consumerState.tailIndex;

        if (head >= tail) {
            if (consumerState.state == QueueState.DRAINING) {
                _finalizeShutdown();
            }
            return false;
        }

        Message storage msg_ = messageQueue[head];
        require(!msg_.processed, "Already processed");

        msg_.processed = true;
        consumerState.headIndex = head + 1;
        consumerState.processedCount += 1;
        consumerState.lastProcessedTimestamp = block.timestamp;

        processorRewards[msg.sender] += REWARD_PER_MESSAGE;
        pendingWithdrawals[msg_.sender] += 0.005 ether;

        emit MessageProcessed(head, msg.sender);

        if (consumerState.state == QueueState.DRAINING && consumerState.headIndex >= tail) {
            _finalizeShutdown();
        }

        return true;
    }

    function initiateGracefulShutdown() external onlyOwner whenActive {
        consumerState.state = QueueState.DRAINING;
        drainInitiatedAt = block.timestamp;
        emit ShutdownInitiated(block.timestamp);
    }

    function forceShutdown() external onlyOwner {
        require(consumerState.state == QueueState.DRAINING, "Must be draining");
        require(block.timestamp >= drainInitiatedAt + DRAIN_TIMEOUT, "Timeout not reached");
        _finalizeShutdown();
    }

    function _finalizeShutdown() internal {
        consumerState.state = QueueState.SHUTDOWN;
        emit GracefulShutdownComplete(consumerState.processedCount);
    }

    function claimRewards() external nonReentrant {
        uint256 reward = processorRewards[msg.sender];
        require(reward > 0, "No rewards");

        processorRewards[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: reward}("");
        require(success, "Transfer failed");
    }

    function withdrawPending() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        require(amount > 0, "Nothing to withdraw");

        // During draining, allow withdrawals but track state transition
        if (consumerState.state == QueueState.DRAINING) {
            // Check if all messages processed after this withdrawal
            uint256 head = consumerState.headIndex;
            uint256 tail = consumerState.tailIndex;
            pendingWithdrawals[msg.sender] = 0;

            (bool success, ) = payable(msg.sender).call{value: amount}("");
            require(success, "Transfer failed");

            // Race: external call above could trigger processNextMessage via fallback
            // Re-read state after external call
            if (head >= tail && consumerState.state == QueueState.DRAINING) {
                _finalizeShutdown();
            }
        } else {
            pendingWithdrawals[msg.sender] = 0;
            (bool success, ) = payable(msg.sender).call{value: amount}("");
            require(success, "Transfer failed");
        }
    }

    function getQueueDepth() external view returns (uint256) {
        return consumerState.tailIndex - consumerState.headIndex;
    }

    function emergencyRefund(uint256 fromIndex, uint256 toIndex) external onlyOwner {
        require(consumerState.state == QueueState.SHUTDOWN, "Not shutdown");
        for (uint256 i = fromIndex; i < toIndex && i < consumerState.tailIndex; i++) {
            Message storage msg_ = messageQueue[i];
            if (!msg_.processed) {
                uint256 refund = 0.01 ether;
                msg_.processed = true;
                pendingWithdrawals[msg_.sender] += refund;
            }
        }
    }

    receive() external payable {}
}
